def close(x, ref, rtol: float = 1e-12, atol: float = 1e-12) -> bool:
    a = np.asarray(x)
    r = np.asarray(ref)
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    ok = True
    for u, v in zip(a.flat, r.flat):
        if math.isinf(v) or math.isinf(u):
            if u != v:
                print('mismatch', u, v)
                ok = False
        elif abs(u - v) > atol + rtol * abs(v):
            print('mismatch', u, v)
            ok = False
    return ok

def same(x, ref) -> bool:
    a = np.asarray(x)
    r = np.asarray(ref)
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    for u, v in zip(a.flat, r.flat):
        if u != v:
            print('mismatch', u, v)
            return False
    return True

Gd = np.zeros((9, 9))
for i in range(9):
    for j in range(9):
        if i != j and (i * 5 + j * 3) % 7 < 3:
            Gd[i, j] = float((i + 2 * j) % 5 + 1)
Gs = sp.csr_array(Gd)

@test
def test_shortest():
    for m, dref, pref, uref, upref in [
            ("D", sp_D_1_d, sp_D_1_p, sp_D_0_d, sp_D_0_p),
            ("BF", sp_BF_1_d, sp_BF_1_p, sp_BF_0_d, sp_BF_0_p),
            ("FW", sp_FW_1_d, sp_FW_1_p, sp_FW_0_d, sp_FW_0_p),
            ("J", sp_J_1_d, sp_J_1_p, sp_J_0_d, sp_J_0_p)]:
        d, p = cg.shortest_path(Gs, method=m, directed=True, return_predecessors=True)
        assert close(d, dref) and same(p, pref)
        d, p = cg.shortest_path(Gs, method=m, directed=False, return_predecessors=True)
        assert close(d, uref) and same(p, upref)
    d, p = cg.shortest_path(Gs, unweighted=True, return_predecessors=True)
    assert close(d, sp_unw_d) and same(p, sp_unw_p)
    d1, p1, s1 = cg.dijkstra(Gs, indices=[0, 4], min_only=True, return_predecessors=True)
    assert close(d1, dj_min_d) and same(p1, dj_min_p) and same(s1, dj_min_s)
    assert close(cg.dijkstra(Gs, indices=2, limit=4.0), dj_lim)
    assert close(cg.shortest_path(Gd), sp_FW_1_d)
    Neg = Gd.copy()
    Neg[1, 0] = -1.0
    Neg[3, 2] = -0.5
    NegS = sp.csr_array(Neg)
    d, p = cg.johnson(NegS, return_predecessors=True)
    assert close(d, jo_d) and same(p, jo_p)
    d, p = cg.bellman_ford(NegS, indices=[1, 3], return_predecessors=True)
    assert close(d, bf_d) and same(p, bf_p)
    cyc = sp.csr_array(np.array([[0., 1.], [-2., 0.]]))
    raised = False
    try:
        cg.bellman_ford(cyc)
    except cg.NegativeCycleError:
        raised = True
    assert raised
    P = cg.shortest_path(Gs, return_predecessors=True)[1]
    assert close(cg.construct_dist_matrix(Gs, P), cdm)
test_shortest()

@test
def test_traversal():
    Cg = np.zeros((10, 10))
    for e in [(0, 1), (1, 2), (2, 0), (3, 4), (4, 5), (5, 3), (2, 3), (6, 7), (8, 8), (7, 6), (9, 6)]:
        Cg[e[0], e[1]] = 1.0
    Cs = sp.csr_array(Cg)
    nc, lab = cg.connected_components(Cs, directed=True, connection='strong')
    assert nc == scc_n and same(lab, scc_l)
    nc, lab = cg.connected_components(Cs, directed=True, connection='weak')
    assert nc == wcc_n and same(lab, wcc_l)
    assert cg.connected_components(Cs, return_labels=False) == wcc_n
    o, p = cg.breadth_first_order(Gs, 3, directed=True)
    assert same(o, bfo_1_o) and same(p, bfo_1_p)
    o, p = cg.breadth_first_order(Gs, 3, directed=False)
    assert same(o, bfo_0_o) and same(p, bfo_0_p)
    o, p = cg.depth_first_order(Gs, 3, directed=True)
    assert same(o, dfo_1_o) and same(p, dfo_1_p)
    o, p = cg.depth_first_order(Gs, 3, directed=False)
    assert same(o, dfo_0_o) and same(p, dfo_0_p)
    assert close(cg.breadth_first_tree(Gs, 0, directed=False).toarray(), bft_d)
    assert close(cg.depth_first_tree(Gs, 0, directed=True).toarray(), dft_d)
    assert cg.structural_rank(Cs) == srank
test_traversal()

@test
def test_other():
    assert close(cg.minimum_spanning_tree(Gs).toarray(), mst_d)
    assert same(cg.reverse_cuthill_mckee(Gs), rcm)
    assert same(cg.reverse_cuthill_mckee(sp.csr_array(Gd + Gd.T), symmetric_mode=True), rcm_sym)
    assert close(cg.laplacian(Gd), lap_d)
    assert close(cg.laplacian(Gd, normed=True), lap_n)
    L, dg = cg.laplacian(Gs, normed=True, return_diag=True)
    assert close(L.toarray(), lap_sn) and close(dg, lap_sdiag)
    assert close(cg.laplacian(Gd, use_out_degree=True), lap_out)
    Fc = sp.csr_array((Gd * 2).astype(int))
    r = cg.maximum_flow(Fc, 0, 8)
    assert r.flow_value == mf_v and same(r.flow.toarray(), mf_f)
    r2 = cg.maximum_flow(Fc, 0, 8, method='edmonds_karp')
    assert r2.flow_value == mf_v and same(r2.flow.toarray(), mf_ek)
test_other()
